INSERT INTO `habilidades` VALUES (1,'Revolver','Ataque','Dispara su revolver causando daño a los enemigos.',1),(2,'Defiance','Ataque Secundario','Realiza un poderoso ataque cuerpo a cuerpo.',1),(3,'Reversal','Habilidad','Absorbe el daño recibido y lo devuelve a los enemigos.',1),(4,'Nether Step','Movimiento','Se desplaza rápidamente en la dirección elegida.',1),(5,'Accursed Arm','Definitiva','Canaliza un poderoso disparo capaz de eliminar a un enemigo.',1),(6,'Burst Cannon','Ataque','Dispara un proyectil explosivo que inflige daño en área.',2),(7,'Kinetic Burst','Ataque Secundario','Libera una explosión que empuja a los enemigos cercanos.',2),(8,'Siege Shield','Habilidad','Despliega un gran escudo frontal para protegerse.',2),(9,'Shoulder Bash','Movimiento','Carga hacia delante derribando a los enemigos.',2),(10,'Assert Dominance','Definitiva','Salta a una ubicación, se vuelve inmune y aturde a los enemigos cercanos.',2),(11,'Chrono-Cannon','Ataque','Dispara una carga de energía cuyo daño aumenta al cargarse.',3),(12,'Setback','Ataque Secundario','Retrocede a un enemigo a una posición anterior en el tiempo.',3),(13,'Stasis Field','Habilidad','Crea una barrera que detiene los proyectiles enemigos.',3),(14,'Second Chance','Movimiento','Regresa a la posición y estado que tenía unos segundos antes.',3),(15,'Exile','Definitiva','Expulsa a los enemigos del flujo temporal, dejándolos fuera del combate temporalmente.',3),(16,'Judgement','Ataque','Lanza ondas de energía con su martillo causando daño a los enemigos.',4),(17,'Reckoning','Ataque Secundario','Invoca un área sagrada que atrae y daña a los enemigos.',4),(18,'Conviction','Habilidad','Embiste hacia delante, empujando y dañando a los enemigos.',4),(19,'Sanctuary','Movimiento','Invoca muros sagrados que bloquean el paso y los proyectiles.',4),(20,'Deliverance','Definitiva','Se eleva por el aire y se lanza contra un enemigo causando un gran impacto.',4),(21,'Blunderbuss','Ataque','Dispara una escopeta improvisada que i