INSERT INTO `secciones` VALUES (1,'Nuevo campeón: Lillith','Clase: Daño | Disponible desde el parche 3.4. Su ultimate Tormenta de Sombras inflige daño masivo y reduce la curación enemiga 3s.','https://www.youtube.com/watch?v=fC6WSgSVv6M'),(2,'Parche 3.4 lanzado','Cambios: Fernando -8% daño escudo. Maeve +5% velocidad. Androxus: Reversal refleja áreas. Koga: Shadow Step -0.3s cooldown.',NULL),(3,'Evento: Semana del Dragón','Del 1 al 7 de junio. Doble XP en clasificatorias. Recompensa final: skin Dragón de Jade para Koga.',NULL),(4,'Stone Keep','Modo: Asalto | 5v5 | Dificultad: Media. Mapa simétrico con pasillo central como choke point principal.',NULL),(5,'Jaguar Falls','Modo: Escolta | 5v5 | Dificultad: Alta. Vegetación densa y múltiples niveles de altura para campeones con movilidad.',NULL),(6,'Frozen Guard','Modo: Sitio | 5v5 | Dificultad: Baja. Escenario invernal con tres puntos de captura simultáneos.',NULL),(7,'Asalto','5v5 | Capturar y mantener el punto central. Al mejor de 3 rondas. Las eliminaciones otorgan créditos.',NULL),(8,'Escolta','5v5 | Escoltar o detener la carga. Los equipos intercambian roles al final de la primera ronda.',NULL),(9,'Sitio','5v5 | Controlar múltiples puntos. Primer equipo en llegar a 500 puntos gana.',NULL);
/*!40000 ALTER TABLE `secciones` ENABLE KEYS */;
UNLOCK TABLES;

